By using it as a derived table: SELECT a.*, b.[Close] FROM ( SELECT [Date], Symbol, MAX([Time]) as max_time FROM MinuteData2016 WHERE (Symbol = 'AAPL' or Symbol = 'ADBE') AND ([Date]=20171102 or [Date]= 20171103 ) GROUP BY Symbol,[Date]) a INNER JOIN MinuteData2016 b ON a.[Date] = b.[Date] AND a.Symbol = b.Symbol AND b.Time = max_time AND a.[Time] > 1600 GROUP BY a.Symbol,a.[Date] ;
Or a CTE: WITH CTE AS ( SELECT [Date], Symbol, MAX([Time]) as max_time FROM MinuteData2016 WHERE (Symbol = 'AAPL' or Symbol = 'ADBE') AND ([Date]=20171102 or [Date]= 20171103 ) GROUP BY Symbol,[Date] ) SELECT a.*, b.[Close] FROM CTE a INNER JOIN MinuteData2016 b ON a.[Date] = b.[Date] AND a.Symbol = b.Symbol AND b.Time = max_time WHERE (a.Symbol = 'AAPL' or a.Symbol = 'ADBE') AND (a.[Date]=20171102 or a.[Date]= 20171103 ) AND a.[Time] > 1600 GROUP BY a.Symbol,a.[Date] ;
